class VectorClock:
    """Per-node counter vector for causality detection."""
    def __init__(self, node_id, all_ids):
        self.node = node_id
        self.ids = list(all_ids)
        self.v = {nid: 0 for nid in self.ids}

    def local_event(self):
        """Rule 1: increment own entry on any local event."""
        self.v[self.node] += 1
        return dict(self.v)

    def send(self):
        """Rule 2: attach current vector to outgoing message.
        (Conceptually we increment on send; many implementations
        increment on local_event, then send the snapshot.)"""
        return dict(self.v)

    def receive(self, msg_clock):
        """Rule 3: per-component max, then increment own entry."""
        for nid in self.ids:
            self.v[nid] = max(self.v[nid], msg_clock.get(nid, 0))
        self.v[self.node] += 1
        return dict(self.v)

    def snapshot(self):
        return dict(self.v)

def happens_before(a, b):
    """True if a -> b: every component of a <= b, and a != b."""
    le_all = all(a[k] <= b[k] for k in a)
    ne = any(a[k] != b[k] for k in a)
    return le_all and ne

def relation(a_name, a, b_name, b):
    if happens_before(a, b):  return f"{a_name} -> {b_name} (causal)"
    if happens_before(b, a):  return f"{b_name} -> {a_name} (causal)"
    return f"{a_name} || {b_name} (concurrent)"

# 3-node system
ids = ['A', 'B', 'C']
A, B, C = (VectorClock(n, ids) for n in ids)

# A local event, then A sends to B
A.local_event()                  # A=[1,0,0]
B.receive(A.send())              # B=[1,1,0]
# B sends to C
C.receive(B.send())              # C=[1,1,1]
# A does another local event, sends to C
A.local_event()                  # A=[2,0,0]
C.receive(A.send())              # C=[2,1,2]
# B local event, sends to A
B.local_event()                  # B=[1,2,0]
A.receive(B.send())              # A: max([2,0,0],[1,2,0])=[2,2,0], inc A's own -> [3,2,0]

va, vc = A.snapshot(), C.snapshot()
print("A clock:", va)            # {'A':3,'B':2,'C':0}
print("C clock:", vc)            # {'A':2,'B':1,'C':2}
print("relation A vs C:", relation("A", va, "C", vc))
# Output: A || C (concurrent) -> conflicting siblings in Dynamo/Riak
